    let set = ?acceptContractSet(
      readFile(rcPrimary),
      [],
      rcSupporting.mapIt(readFile(it)),
      AcceptOptions(system: true),
    )
    nimModule(
      set,
      NimOptions(
        importPrefix: "../",
        schemaAccessor: "rcSchema",
        documentsAccessor: "rcDocuments",
